import UIKit

actor ThumbnailLoader {
    private var inFlight: [URL: Task<UIImage, Error>] = [:]
    private var cache: [URL: UIImage] = [:]

    func thumbnail(for url: URL) async throws -> UIImage {
        if let cached = cache[url] { return cached }
        if let task = inFlight[url] { return try await task.value }

        let task = Task { try await Self.render(url) }
        inFlight[url] = task
        defer { inFlight[url] = nil }
        let image = try await task.value
        cache[url] = image
        return image
    }

    private static func render(_ url: URL) async throws -> UIImage {
        let (data, _) = try await URLSession.shared.data(from: url)
        guard let image = UIImage(data: data)?.preparingThumbnail(of: CGSize(width: 160, height: 160)) else {
            throw URLError(.cannotDecodeContentData)
        }
        return image
    }
}

