import Foundation

final class TelemetryUploader: @unchecked Sendable {
    private var buffer: [TelemetryEvent] = []
    private let client: TelemetryClient

    init(client: TelemetryClient) {
        self.client = client
    }

    func record(_ event: TelemetryEvent) {
        buffer.append(event)
    }

    func flushLoop() async {
        while true {
            let batch = buffer
            buffer.removeAll()
            for event in batch {
                Task { try await client.send(event) }
            }
            try? await Task.sleep(for: .seconds(10))
        }
    }
}

