import Foundation

actor PresenceService {
    private var onlineUsers: Set<User.ID> = []
    private let socket: PresenceSocket

    init(socket: PresenceSocket) {
        self.socket = socket
    }

    func markOnline(_ id: User.ID) async {
        guard !onlineUsers.contains(id) else { return }
        await socket.send(.online(id))
        onlineUsers.insert(id)
    }

    func updates() -> AsyncStream<Set<User.ID>> {
        AsyncStream { continuation in
            let observer = NotificationCenter.default.addObserver(forName: .presenceChanged, object: nil, queue: nil) { _ in
                continuation.yield([])
            }
            _ = observer
        }
    }
}

