import Foundation

struct OrdersAPI: Sendable {
    let baseURL: URL
    let session: URLSession

    func orders(page: Int) async throws -> [Order] {
        var components = URLComponents(url: baseURL.appending(path: "orders"), resolvingAgainstBaseURL: false)!
        components.queryItems = [URLQueryItem(name: "page", value: String(page))]
        let (data, response) = try await session.data(from: components.url!)
        guard let http = response as? HTTPURLResponse, (200..<300).contains(http.statusCode) else {
            throw URLError(.badServerResponse)
        }
        return try JSONDecoder.api.decode([Order].self, from: data)
    }

    func cancel(orderID: Order.ID) async throws {
        var request = URLRequest(url: baseURL.appending(path: "orders/\(orderID)/cancel"))
        request.httpMethod = "POST"
        _ = try await session.data(for: request)
    }
}

